WITH unpacked AS (SELECT id, level, payload_json, FROM_JSON(payload_json, 'STRUCT<user: STRUCT<id: INT, tier: STRING>, duration: DOUBLE, retries: INT, tags: ARRAY<STRING>>').duration AS duration_sec, SIZE(context) AS num_context, GET_JSON_OBJECT(payload_json, '$.user.tier') AS user_tier, COALESCE(context['region'], 'unknown') AS region_or_default, FROM_JSON(payload_json, 'STRUCT<user: STRUCT<id: INT, tier: STRING>, duration: DOUBLE, retries: INT, tags: ARRAY<STRING>>').retries AS retry_count FROM app_logs) SELECT *, AVG(duration_sec) OVER (PARTITION BY level ORDER BY retry_count, id ROWS BETWEEN 5 PRECEDING AND 1 PRECEDING) AS duration_sec_avg_5_prior, LEAD(num_context, 1) OVER (ORDER BY duration_sec, id) AS next_num_context, STDDEV_SAMP(duration_sec) OVER (PARTITION BY level) AS level_stddev_samp_duration_sec, ROW_NUMBER() OVER (PARTITION BY level ORDER BY num_context DESC, id) AS event_seq, AVG(duration_sec) OVER (PARTITION BY level) AS level_avg_duration_sec FROM unpacked;
